import { shippingFee } from './shipping.js'
import { cents } from '../util/money.js'
export function createInvoice(order) {
  const subtotal = order.lines.reduce((sum, line) => sum + line.price * line.quantity, 0)
  return { subtotal: cents(subtotal), shipping: cents(shippingFee(order.weightKg, order.country)) }
}

