import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { totalRevenue, topCustomer, monthlyTotals } from './report.mjs'
const orders = JSON.parse(readFileSync('orders.json', 'utf8')), paid = orders.filter(order => order.status === 'paid')
const value = order => order.quantity * order.unitPrice, round = amount => Math.round(amount * 100)
const total = paid.reduce((sum, order) => sum + value(order), 0), byCustomer = {}, months = {}
for (const order of paid) { byCustomer[order.customer] = (byCustomer[order.customer] ?? 0) + value(order); months[order.date.slice(0, 7)] = (months[order.date.slice(0, 7)] ?? 0) + value(order) }
const top = Object.entries(byCustomer).sort((a, b) => round(b[1]) - round(a[1]) || a[0].localeCompare(b[0]))[0][0]
assert.equal(round(totalRevenue(orders)), round(total))
assert.equal(topCustomer(orders), top)
const got = monthlyTotals(orders)
assert.deepEqual(Object.keys(got).sort(), Object.keys(months).sort())
for (const month of Object.keys(months)) assert.equal(round(got[month]), round(months[month]))
const written = JSON.parse(readFileSync('out/report.json', 'utf8'))
assert.equal(round(written.totalRevenue), round(total)); assert.equal(written.topCustomer, top)
for (const month of Object.keys(months)) assert.equal(round(written.monthlyTotals[month]), round(months[month]))
